",\"annotation\":\"str | Path\",\"kind\":\"keyword_only\",\"default\":null},{\"name\":\"rss_source\",\"meaning\":\"str | Path 类型的输入，参与当前函数的计算。\",\"annotation\":\"str | Path\",\"kind\":\"keyword_only\",\"default\":null},{\"name\":\"config\",\"meaning\":\"AuditConfig 类型的输入，参与当前函数的计算。\",\"annotation\":\"AuditConfig\",\"kind\":\"keyword_only\",\"default\":null}],\"returns\":{\"name\":\"return\",\"annotation\":\"dict[str, Any]\",\"expressions\":[\"{'schema': 'saebase.m4.ground_truth.v1', 'status': 'passed' if all((x == 'passed' for x in parts)) else 'failed', 'sourc\"],\"meaning\":\"当前过程生成的文字说明或标识。\"},\"code\":\"def evaluate_ground_truth(\\n    *, sar_source: str | Path, rss_source: str | Path, config: AuditConfig\\n) -> dict[str, Any]:\\n    \\\"\\\"\\\"Never loads LLM/SAE checkpoints or estimates uncertainty from invented data.\\n\\n    Ground truths and upstream numerical estimators are separate objects. The\\n    original source file SHA-256 is frozen in the audit for repeatability.\\n    \\\"\\\"\\\"\\n    sar_sha = source_identity(sar_source, \\\"sar\\\")\\n    rss_sha = source_identity(rss_source, \\\"rss\\\")\\n    sar = load_paper_module(sar_source, paper=\\\"sar\\\")\\n    rss = load_paper_module(rss_source, paper=\\\"rss\\\")\\n    factor = evaluate_degradation(config)\\n    interactions = verify_original_sar(sar, seed=7)\\n    direction = verify_original_rss(rss, seed=11)\\n    # Coalition selection and RSS variant selection are independently reseeded\\n    # without fitting on held-out responses. These are estimator stress tests\\n    # on analytic data, not fabricated empirical LLM replicates.\\n    sar_resampled = []\\n    rss_resampled = []\\n    for seed in config.evaluation_seeds:\\n        trial = verify_original_sar(sar, seed=seed, M=512, n_fit=350)\\n        sar_resampled.append(\\n            {\\n                \\\"evaluation_seed\\\": seed,\\n                \\\"cases\\\": trial,\\n                \\\"status\\\": \\\"passed\\\"\\n                if all(x[\\\"status\\\"] == \\\"passed\\\" for x in trial.values())\\n                else \\\"failed\\\",\\n            }\\n        )\\n        trial_rss = verify_original_rss(rss, seed=seed)\\n        rss_resampled.append({\\\"evaluation_seed\\\": seed, **trial_rss})\\n    negatives = {\\n        \\\"coordinate_invariance\\\": check_coordinates(seed=10),\\n        \\\"sar_negative_controls\\\": check_sar_negatives(sar, seed=20),\\n        \\\"rss_negative_controls\\\": check_rss_controls(rss, seed=21),\\n    }\\n    parts = [\\n        *(v[\\\"status\\\"] for v in factor.values()),\\n        *(v[\\\"status\\\"] for v in interactions.values()),\\n        direction[\\\"status\\\"],\\n        *(v[\\\"status\\\"] for v in negatives.values()),\\n        *(x[\\\"status\\\"] for x in sar_resampled),\\n        *(x[\\\"status\\\"] for x in rss_resampled),\\n    ]\\n    return {\\n        \\\"schema\\\": \\\"saebase.m4.ground_truth.v1\\\",\\n        \\\"status\\\": \\\"passed\\\" if all(x == \\\"passed\\\" for x in parts) else \\\"failed\\\",\\n        \\\"source_provenance\\\": {\\n    ⋮\\n            \\\"sar_upstream_orders\\\": [1, 2],\\n            \\\"rss_selection_and_held_out_disjoint\\\": True,\\n        },\\n        \\\"factor_cases\\\": factor,\\n        \\\"known_interaction_cases\\\": interactions,\\n        \\\"known_rss_direction_case\\\": direction,\\n        \\\"coalition_reseed_trials\\\": sar_resampled,\\n        \\\"rss_reseed_trials\\\": rss_resampled,\\n        \\\"negative_invariance_controls\\\": negatives,\\n    }\",\"line\":16}},{\"type\":\"reference\",\"label\":\"完整源码\",\"path\":\"tasks/benchmark/reliability/ground_truth_report.py\",\"line\":16}]},{\"id\":\"code:function:tasks.benchmark.reliability.interaction_truth:behavior\",\"kind\":\"function\",\"source_symbol\":\"behavior\",\"path\":\"tasks/benchmark/reliability/interaction_truth.py\",\"evidence\":[\"tasks/benchmark/reliability/interaction_truth.py:10\"],\"line\":10,\"signature\":\"def behavior(mask, case: str)\",\"context_term_ids\":[],\"attributes\":[{\"type\":\"interface\",\"label\":\"函数接口\",\"interface\":{\"name\":\"behavior\",\"signature\":\"def behavior(mask, case: str)\",\"parameters\":[{\"name\":\"mask\",\"meaning\":\"传入当前函数的具名数据，具体使用位置见源码。\",\"annotation\":\"\",\"kind\":\"positional\",\"default\":null},{\"name\":\"case\",\"meaning\":\"str 类型的输入，参与当前函数的计算。\",\"annotation\":\"str\",\"kind\":\"positional\",\"default\":null}],\"returns\":{\"name\":\"return\",\"annotation\":\"由源码推导\",\"expressions\":[\"value\"],\"meaning\":\"由代码中的 return 表达式产生的结果。\"},\"code\":\"def behavior(mask, case: str):\\n    mask = np.asarray(mask, dtype=bool)\\n    if mask.ndim != 2 or mask.shape[1] < 3 or case not in CASES:\\n        raise ValueError(\\\"invalid interaction mask/degree\\\")\\n    x = 2 * mask.astype(np.float64) - 1\\n    value = 5 + 0.3 * x[:, 0] - 0.8 * x[:, 1] + 1.3 * x[:, 2]\\n    if mask.shape[1] > 3:\\n        value += 0.5 * x[:, 3]\\n    if case in (\\\"pairwise\\\", \\\"third_order\\\"):\\n        value += 2.5 * x[:, 0] * x[:, 1]\\n    if case == \\\"third_order\\\":\\n        value += 3.5 * x[:, 0] * x[:, 1] * x[:, 2]\\n    return value\",\"line\":10}},{\"type\":\"reference\",\"label\":\"完整源码\",\"path\":\"tasks/benchmark/reliability/interaction_truth.py\",\"line\":10}]},{\"id\":\"code:function:tasks.benchmark.reliability.interaction_truth:exact_order_energy\",\"kind\":\"function\",\"source_symbol\":\"exact_order_energy\",\"path\":\"tasks/benchmark/reliability/interaction_truth.py\",\"evidence\":[\"tasks/benchmark/reliability/interaction_truth.py:25\"],\"line\":25,\"signature\":\"def exact_order_energy(case: str, K: int=4) -> dict[int, float]\",\"context_term_ids\":[],\"attributes\":[{\"type\":\"interface\",\"label\":\"函数接口\",\"interface\":{\"name\":\"exact_order_energy\",\"signature\":\"def exact_order_energy(case: str, K: int=4) -> dict[int, float]\",\"parameters\":[{\"name\":\"case\",\"meaning\":\"str 类型的输入，参与当前函数的计算。\",\"annotation\":\"str\",\"kind\":\"positional\",\"default\":null},{\"name\":\"K\",\"meaning\":\"int 类型的输入，参与当前函数的计算。\",\"annotation\":\"int\",\"kind\":\"positional\",\"default\":\"4\"}],\"returns\":{\"name\":\"return\",\"annotation\":\"dict[int, float]\",\"expressions\":[\"result\"],\"meaning\":\"函数返回的 dict[int, float] 类型结果。\"},\"code\":\"def exact_order_energy(case: str, K: int = 4) -> dict[int, float]:\\n    \\\"\\\"\\\"Fourier expansion under uniform Boolean coalitions: known degree truth.\\\"\\\"\\\"\\n    if case not in CASES or K < 4 or K > 8:\\n        raise ValueError(\\\"unsupported synthetic truth dimensions\\\")\\n    mask = np.asarray(list(product((False, True), repeat=K)), dtype=bool)\\n    y = behavior(mask, case)\\n    x = 2 * mask.astype(float) - 1\\n    result = {}\\n    for degree in range(1, K + 1):\\n        energy = 0.0\\n        for subset in combinations(range(K), degree):\\n            basis = np.prod(x[:, subset], axis=1)\\n            coef = float(np.mean(y * basis))\\n            energy += coef * coef\\n        result[degree] = float(energy)\\n    return result\",\"line\":25}},{\"type\":\"reference\",\"label\":\"完整源码\",\"path\":\"tasks/benchmark/reliability/interaction_truth.py\",\"line\":25}]},{\"id\":\"code:function:tasks.benchmark.reliability.interaction_truth:verify_original_sar\",\"kind\":\"function\",\"source_symbol\":\"verify_original_sar\",\"path\":\"tasks/benchmark/reliability/interaction_truth.py\",\"evidence\":[\"tasks/benchmark/reliability/interaction_truth.py:43\"],\"line\":43,\"signature\":\"def verify_original_sar(paper, *, seed: int=7, M: int=512, n_fit: int=350) -> dict\",\"context_term_ids\":[],\"attributes\":[{\"type\":\"interface\",\"label\":\"函数接口\",\"interface\":{\"name\":\"verify_original_sar\",\"signature\":\"def verify_original_sar(paper, *, seed: int=7, M: int=512, n_fit: int=350) -> dict\",\"parameters\":[{\"name\":\"paper\",\"meaning\":\"传入当前函数的具名数据，具体使用位置见源码。\",\"annotation\":\"\",\"kind\":\"positional\",\"default\":null},{\"name\":\"seed\",\"meaning\":\"随机数初始化种子\",\"annotation\":\"int\",\"kind\":\"keyword_only\",\"default\":\"7\"},{\"name\":\"M\",\"meaning\":\"int 类型的输入，参与当前函数的计算。\",\"annotation\":\"int\",\"kind\":\"keyword_only\",\"default\":\"512\"},{\"name\":\"n_fit\",\"meaning\":\"int 类型的输入，参与当前函数的计算。\",\"annotation\":\"int\",\"kind\":\"keyword_only\",\"default\":\"350\"}],\"returns\":{\"name\":\"return\",\"annotation\":\"dict\",\"expressions\":[\"cases\"],\"meaning\":\"函数返回的 dict 类型结果。\"},\"code\":\"def verify_original_sar(paper, *, seed: int = 7, M: int = 512, n_fit: int = 350) -> dict:\\n    \\\"\\\"\\\"Call original SAR estimator; do not redefine its numerical definition.\\\"\\\"\\\"\\n    if not callable(getattr(paper, \\\"coalitions\\\", None)) or not callable(\\n        getattr(paper, \\\"sar\\\", None)\\n    ):\\n        raise TypeError(\\\"trusted original SAR module must expose coalitions and sar\\\")\\n    masks, fit, held = paper.coalitions(K=4, M=M, n_fit=n_fit, seed=seed)\\n    cases = {}\\n    for case in CASES:\\n        g = behavior(masks, case)\\n        g_full = float(behavior(np.ones((1, 4), dtype=bool), case)[0])\\n        upstream = paper.sar(g, masks, fit, held, g_full=g_full)\\n        energy = exact_order_energy(case)\\n        first = float(upstream[\\\"sar1\\\"])\\n        second = float(upstream[\\\"sar2\\\"])\\n        if case == \\\"first_order\\\":\\n            passed = first < 1e-8 and second < 1e-8 and energy[2] < 1e-12 and energy[3] < 1e-12\\n        elif case == \\\"pairwise\\\":\\n            passed = first > 0.02 and second < 1e-8 and energy[2] > 1.0 and energy[3] < 1e-12\\n        else:\\n            passed = first > 0.02 and second > 0.02 and energy[3] > 1.0\\n        cases[case] = {\\n            \\\"status\\\": \\\"passed\\\" if passed else \\\"failed\\\",\\n            \\\"oracle_energy_by_order\\\": {str(k): v for k, v in energy.items()},\\n            \\\"native_sar1\\\": first,\\n            \\\"native_sar2\\\": second,\\n            \\\"n_fit\\\": len(fit),\\n            \\\"n_held_out\\\": len(held),\\n            \\\"seed\\\": seed,\\n            \\\"note\\\": \\\"No SAR3 estimator exists in the original SAR paper implementation\\\",\\n        }\\n    return cases\",\"line\":43}},{\"type\":\"reference\",\"label\":\"完整源码\",\"path\":\"tasks/benchmark/reliability/interaction_truth.py\",\"line\":43}]},{\"id\":\"code:function:tasks.benchmark.reliability.rss_truth:fixture\",\"kind\":\"function\",\"source_symbol\":\"fixture\",\"path\":\"tasks/benchmark/reliability/rss_truth.py\",\"evidence\":[\"tasks/benchmark/reliability/rss_truth.py:7\"],\"line\":7,\"signature\":\"def fixture(*, seed: int=11, n_select: int=40, n_held_out: int=40)\",\"context_term_ids\":[],\"attributes\":[{\"type\":\"interface\",\"label\":\"函数接口\",\"interface\":{\"name\":\"fixture\",\"signature\":\"def fixture(*, seed: int=11, n_select: int=40, n_held_out: int=40)\",\"parameters\":[{\"name\":\"seed\",\"meaning\":\"随机数初始化种子\",\"annotation\":\"int\",\"kind\":\"keyword_only\",\"default\":\"11\"},{\"name\":\"n_select\",\"meaning\":\"int 类型的输入，参与当前函数的计算。\",\"annotation\":\"int\",\"kind\":\"keyword_only\",\"default\":\"40\"},{\"name\":\"n_held_out\",\"meaning\":\"int 类型的输入，参与当前函数的计算。\",\"annotation\":\"int\",\"kind\":\"keyword_only\",\"default\":\"40\"}],\"returns\":{\"name\":\"return\",\"annotation\":\"由源码推导\",\"expressions\":[\"{'selection': selection, 'held_out': held, 'support': support, 'direction': direction, 'seed': seed, 'selection_ids': tu\"],\"meaning\":\"由代码中的 return 表达式产生的结果。\"},\"code\":\"def fixture(*, seed: int = 11, n_select: int = 40, n_held_out: int = 40):\\n    rng = np.random.default_rng(seed)\\n    if n_select < 5 or n_held_out < 5:\\n        raise ValueError(\\\"need independent selection and held-out variants\\\")\\n    K = 12\\n    support = np.asarray([1, 4, 9], dtype=int)\\n    direction = np.asarray([1, -1, 1], dtype=int)\\n    scale = np.asarray([2.0, 1.6, 1.2])\\n    selection = rng.normal(0, 0.005, (n_select, K))\\n    held = rng.normal(0, 0.005, (n_held_out, K))\\n    selection[:, support] += scale * direction\\n    held[:, support] += scale * direction\\n    return {\\n        \\\"selection\\\": selection,\\n        \\\"held_out\\\": held,\\n        \\\"support\\\": support,\\n        \\\"direction\\\": direction,\\n        \\\"seed\\\": seed,\\n        \\\"selection_ids\\\": tuple(f\\\"selection-{i}\\\" for i in range(n_select)),\\n        \\\"held_out_ids\\\": tuple(f\\\"held_out-{i}\\\" for i in range(n_held_out)),\\n    }\",\"line\":7}},{\"type\":\"reference\",\"label\":\"完整源码\",\"path\":\"tasks/benchmark/reliability/rss_truth.py\",\"line\":7}]},{\"id\":\"code:function:tasks.benchmark.reliability.rss_truth:verify_original_rss\",\"kind\":\"function\",\"source_symbol\":\"verify_original_rss\",\"path\":\"tasks/benchmark/reliability/rss_truth.py\",\"evidence\":[\"tasks/benchmark/reliability/rss_truth.py:30\"],\"line\":30,\"signature\":\"def verify_original_rss(paper, *, seed: int=11) -> dict\",\"context_term_ids\":[],\"attributes\":[{\"type\":\"interface\",\"label\":\"函数接口\",\"interface\":{\"name\":\"verify_original_rss\",\"signature\":\"def verify_original_rss(paper, *, seed: int=11) -> dict\",\"parameters\":[{\"name\":\"paper\",\"meaning\":\"传入当前函数的具名数据，具体使用位置见源码。\",\"annotation\":\"\",\"kind\":\"positional\",\"default\":null},{\"name\":\"seed\",\"meaning\":\"随机数初始化种子\",\"annotation\":\"int\",\"kind\":\"keyword_only\",\"default\":\"11\"}],\"returns\":{\"name\":\"return\",\"annotation\":\"dict\",\"expressions\":[\"{'status': 'passed' if passed else 'failed', 'source_estimator': 'original RSS / held_out_rate', 'expected_support': f['\"],\"meaning\":\"函数返回的 dict 类型结果。\"},\"code\":\"def verify_original_rss(paper, *, seed: int = 11) -> dict:\\n    if not callable(getattr(paper, \\\"rss\\\", None)) or not callable(\\n        getattr(paper, \\\"held_out_rate\\\", None)\\n    ):\\n        raise TypeError(\\\"trusted original RSS module requires rss and held_out_rate\\\")\\n    f = fixture(seed=seed)\\n    if set(f[\\\"selection_ids\\\"]) & set(f[\\\"held_out_ids\\\"]):\\n        raise ValueError(\\\"RSS selection/held-out leakage\\\")\\n    support, direction, mean = paper.rss(f[\\\"selection\\\"], rho=0.8, kappa=0.9, tau=0.1, M=12, K=3)\\n    rates = paper.held_out_rate(f[\\\"held_out\\\"], support, direction, tau=0.1)\\n    passed = (\\n        np.array_equal(support, f[\\\"support\\\"])\\n        and np.array_equal(direction, f[\\\"direction\\\"])\\n        and bool(np.allclose(rates, 1.0))\\n        and np.isfinite(mean)\\n    )\\n    # Modify held-out only; selection-derived support/direction may not change.\\n    flipped = f[\\\"held_out\\\"].copy()\\n    flipped[:, f[\\\"support\\\"]] *= -1\\n    flipped_rates = paper.held_out_rate(flipped, support, direction, tau=0.1)\\n    passed = passed and bool(np.allclose(flipped_rates, 0.0))\\n    empty, empty_direction, undefined = paper.rss(\\n        np.zeros_like(f[\\\"selection\\\"]), rho=0.8, kappa=0.9, tau=0.1, M=12, K=3\\n    )\\n    passed = passed and len(empty) == 0 and len(empty_direction) == 0 and np.isnan(undefined)\\n    return {\\n        \\\"status\\\": \\\"passed\\\" if passed else \\\"failed\\\",\\n        \\\"source_estimator\\\": \\\"original RSS / held_out_rate\\\",\\n        \\\"expected_support\\\": f[\\\"support\\\"].tolist(),\\n        \\\"selected_support\\\": support.tolist(),\\n        \\\"expected_direction\\\": f[\\\"direction\\\"].tolist(),\\n        \\\"selected_direction\\\": direction.tolist(),\\n        \\\"mean_rss\\\": float(mean) if np.isfinite(mean) else None,\\n        \\\"held_out_persistence\\\": rates.tolist(),\\n        \\\"flipped_held_out_persistence\\\": flipped_rates.tolist(),\\n        \\\"n_selection\\\": len(f[\\\"selection\\\"]),\\n        \\\"n_held_out\\\": len(f[\\\"held_out\\\"]),\\n        \\\"empty_support_status\\\": \\\"undefined\\\" if np.isnan(undefined) else \\\"invalid\\\",\\n        \\\"selection_seed\\\": seed,\\n    }\",\"line\":30}},{\"type\":\"reference\",\"label\":\"完整源码\",\"path\":\"tasks/benchmark/reliability/rss_truth.py\",\"line\":30}]},{\"id\":\"code:module:tasks.benchmark.reliability.controls\",\"kind\":\"module\",\"source_symbol\":\"tasks/benchmark/reliability/controls.py\",\"path\":\"tasks/benchmark/reliability/controls.py\",\"evidence\":[\"tasks/benchmark/reliability/controls.py:1\"],\"line\":1,\"signature\":\"\",\"context_term_ids\":[],\"attributes\":[{\"type\":\"module_contents\",\"label\":\"源码组成\",\"functions\":[\"check_coordinates\",\"check_sar_negatives\",\"check_rss_controls\"],\"classes\":[]},{\"type\":\"code\",\"label\":\"实际代码主要部分\",\"value\":\"def check_coordinates(*, seed: int = 10) -> dict:\\n    \\\"\\\"\\\"Permute/reparameterize paired SAE codes/dictionary with exact reconstruction.\\\"\\\"\\\"\\n    data = make_factors(\\\"superposition\\\", seed=seed)\\n    z = data.test\\n    D = data.dictionary\\n    rng = np.random.default_rng(seed + 999)\\n    permutation = rng.permutation(z.shape[1])\\n    factors = rng.uniform(0.4, 1.8, z.shape[1])\\n    baseline = z @ D.T\\n    permuted = z[:, permutation] @ D[:, permutation].T\\n    scaled = (z * factors) @ (D / factors).T\\n    err_p = float(np.max(np.abs(permuted - baseline)))\\n    err_s = float(np.max(np.abs(scaled - baseline)))\\n    # Null patch is exactly the same activation, independent of dictionaries.\\n    null = float(np.max(np.abs(baseline.copy() - baseline)))\\n    passed = max(err_p, err_s, null) < 1e-10\\n    return {\\n        \\\"status\\\": \\\"passed\\\" if passed else \\\"failed\\\",\\n        \\\"feature_permutation_max_error\\\": err_p,\\n        \\\"positive_coordinate_rescaling_max_error\\\": err_s,\\n        \\\"null_activation_intervention_max_error\\\": null,\\n        \\\"note\\\": \\\"This does not claim RSS MeanRSS is invariant under arbitrary feature rescaling\\\",\\n    }\",\"source\":\"tasks/benchmark/reliability/controls.py\",\"line\":11},{\"type\":\"reference\",\"label\":\"完整模块\",\"path\":\"tasks/benchmark/reliability/controls.py\",\"line\":1},{\"type\":\"class_methods\",\"label\":\"模块中实际定义的函数接口 · 3 个\",\"methods\":[{\"name\":\"check_coordinates\",\"signature\":\"def check_coordinates(*, seed: int=10) -> dict\",\"purpose\":\"Permute/reparameterize paired SAE codes/dictionary with exact reconstruction.\",\"parameters\":[{\"name\":\"seed\",\"meaning\":\"随机数初始化种子\",\"annotation\":\"int\",\"kind\":\"keyword_only\",\"default\":\"10\"}],\"returns\":{\"name\":\"return\",\"annotation\":\"dict\",\"expressions\":[\"{'status': 'passed' if passed else 'failed', 'feature_permutation_max_error': err_p, 'positive_coordinate_rescaling_max_\"],\"meaning\":\"函数返回的 dict 类型结果。\"},\"code\":\"def check_coordinates(*, seed: int = 10) -> dict:\\n    \\\"\\\"\\\"Permute/reparameterize paired SAE codes/dictionary with exact reconstruction.\\\"\\\"\\\"\\n    data = make_factors(\\\"superposition\\\", seed=seed)\\n    z = data.test\\n    D = data.dictionary\\n    rng = np.random.default_rng(seed + 999)\\n    permutation = rng.permutation(z.shape[1])\\n    factors = rng.uniform(0.4, 1.8, z.shape[1])\\n    baseline = z @ D.T\\n    permuted = z[:, permutation] @ D[:, permutation].T\\n    scaled = (z * factors) @ (D / factors).T\\n    err_p = float(np.max(np.abs(permuted - baseline)))\\n    err_s = float(np.max(np.abs(scaled - baseline)))\\n    # Null patch is exactly the same activation, independent of dictionaries.\\n    null = float(np.max(np.abs(baseline.copy() - baseline)))\\n    passed = max(err_p, err_s, null) < 1e-10\\n    return {\\n        \\\"status\\\": \\\"passed\\\" if passed else \\\"failed\\\",\\n        \\\"feature_permutation_max_error\\\": err_p,\\n        \\\"positive_coordinate_rescaling_max_error\\\": err_s,\\n        \\\"null_activation_intervention_max_error\\\": null,\\n        \\\"note\\\": \\\"This does not claim RSS MeanRSS is invariant under arbitrary feature rescaling\\\",\\n    }\",\"line\":11},{\"name\":\"check_sar_negatives\",\"signature\":\"def check_sar_negatives(paper, *, seed: int=20) -> dict\",\"parameters\":[{\"name\":\"paper\",\"meaning\":\"传入当前函数的具名数据，具体使用位置见源码。\",\"annotation\":\"\",\"kind\":\"positional\",\"default\":null},{\"name\":\"seed\",\"meaning\":\"随机数初始化种子\",\"annotation\":\"int\",\"kind\":\"keyword_only\",\"default\":\"20\"}],\"returns\":{\"name\":\"return\",\"annotation\":\"dict\",\"expressions\":[\"{'status': 'passed' if null_pass and affine_pass else 'failed', 'constant_behavior_sar1': float(null['sar1']), 'constant\"],\"meaning\":\"函数返回的 dict 类型结果。\"},\"code\":\"def check_sar_negatives(paper, *, seed: int = 20) -> dict:\\n    masks, fit, held = paper.coalitions(K=4, M=256, n_fit=190, seed=seed)\\n    constant = np.full(len(masks), 5.0, dtype=float)\\n    with warnings.catch_warnings():\\n        warnings.simplefilter(\\\"ignore\\\", RuntimeWarning)\\n        null = paper.sar(constant, masks, fit, held, g_full=5.0)\\n    # Undefined rho2 must not be treated as either positive or negative.\\n    null_pass = abs(null[\\\"sar1\\\"]) < 1e-9 and abs(null[\\\"sar2\\\"]) < 1e-9 and np.isnan(null[\\\"rho2\\\"])\\n    additive = 1.2 + np.asarray(masks, dtype=float) @ np.asarray([1.0, -0.7, 0.3, 2.0])\\n    ordinary = paper.sar(additive, masks, fit, held, g_full=3.8)\\n    affine_pass = ordinary[\\\"sar1\\\"] < 1e-8 and ordinary[\\\"sar2\\\"] < 1e-8\\n    return {\\n        \\\"status\\\": \\\"passed\\\" if null_pass and affine_pass else \\\"failed\\\",\\n        \\\"constant_behavior_sar1\\\": float(null[\\\"sar1\\\"]),\\n        \\\"constant_behavior_rho2_status\\\": \\\"undefined\\\" if np.isnan(null[\\\"rho2\\\"]) else \\\"invalid\\\",\\n        \\\"affine_behavior_sar1\\\": float(ordinary[\\\"sar1\\\"]),\\n        \\\"affine_behavior_sar2\\\": float(ordinary[\\\"sar2\\\"]),\\n    }\",\"line\":36},{\"name\":\"check_rss_controls\",\"signature\":\"def check_rss_control";
